#!/usr/bin/env node
'use strict';

// Produces the complete offline semantic-model plan consumed by the
// Power BI Modeling MCP. The plan contains synthetic fixtures plus the
// schema-only contract for private source-backed device evidence. It never
// serializes private rows, machine-specific paths, or credentials.

const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const fixtureRoot = path.join(root, 'fixtures', 'valid');

function parseCsv(fileName) {
  const text = fs.readFileSync(path.join(fixtureRoot, fileName), 'utf8').replace(/^\uFEFF/, '').trimEnd();
  const lines = text.split(/\r?\n/);
  const parseLine = line => {
    const values = [];
    let value = '';
    let quoted = false;
    for (let index = 0; index < line.length; index += 1) {
      const char = line[index];
      if (char === '"') {
        if (quoted && line[index + 1] === '"') { value += '"'; index += 1; }
        else quoted = !quoted;
      } else if (char === ',' && !quoted) { values.push(value); value = ''; }
      else value += char;
    }
    values.push(value);
    return values;
  };
  const headers = parseLine(lines.shift());
  return lines.filter(Boolean).map(line => Object.fromEntries(headers.map((header, index) => [header, parseLine(line)[index] ?? ''])));
}

const csv = Object.fromEntries(fs.readdirSync(fixtureRoot).filter(name => name.endsWith('.csv')).map(name => [name, parseCsv(name)]));
const asOf = '2026-09-15';
const tenantKey = 1;
