add('Environment', 'Governed synthetic environment scope.', [keyColumn('Environment Key'), C('Environment'), C('Environment Type'), C('Environment Status')], [{ 'Environment Key': 1, Environment: 'Synthetic Lab', 'Environment Type': 'Test', 'Environment Status': 'Active' }]);
