add('Finding Type', 'Governed current-issue and risk-signal definitions.', [keyColumn('Finding Type Key'), C('Finding Category'), C('Finding Title'), C('Default Severity Label'), C('Finding Owner'), C('Signal Type'), C('Signal Confidence'), C('Potential Impact')], findingRows.map(row => ({ 'Finding Type Key': findingTypeKey[row.FindingId], 'Finding Category': row.FindingCategory, 'Finding Title': row.FindingTitle, 'Default Severity Label': row.SeverityLabel, 'Finding Owner': 'Digital Workplace', 'Signal Type': row.SignalType, 'Signal Confidence': row.SignalConfidence, 'Potential Impact': row.PotentialImpact })));
add('Report Metadata', 'Hidden product and evidence metadata utility table.', [C('Product Version'), C('Evidence Disclaimer'), C('Copyright Notice')], [{ 'Product Version': '1.0.0-beta.1', 'Evidence Disclaimer': 'Synthetic evidence only. No tenant or production qualification.', 'Copyright Notice': '© 2026 WorkplaceCloudHub' }], { hidden: true });

